":"nave"}],"office_project_status":[{"project_id":"nave-5","condition":"לא סווג","updated_at":"2024-06-06","short_status":"ביצוע - ביצוע שוטף","manager_issue":"","detailed_status":"יעדי מרץ 23 - 2 מבנים - בהשלמות שונות.\nיעד הנגשה - מרץ 24 - נתקבלו 61 אישורי נגישות, השלמות ב-8 מבנים \nיעדי מרץ 2025 - 61 מבנים  - \n2 קיבלו אישור נגישות\n1 ממתינים לאישור נגישות.\n20 בביצוע \n15 מוכנים לביצוע, בשלבי תיאומים  והכנת חוזים","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"נתנאל","major_issues":"חוסר שת\"פ מפעלים. מתקיימות שיחות רבות בנושא.\nאי בהירות סקרים והנחיות. נשלחות הערות ליועצים לשיפור הנחיות\nגיבוש שיטת עבודה מול  עירייה. מתקיימות פגישות רבות בנושא.","followup_date":"2024-06-06","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":5}},{"project_id":"nave-6","condition":"לא סווג","updated_at":"2024-06-06","short_status":"ביצוע - ביצוע שוטף","manager_issue":"","detailed_status":"השלמת מגרש לביצוע \nחבילה ב'' לשנת 2025 - חתימות לחוזה ביצוע ל-7 מגרשים נוספים.","stage_due_date":"2023-01-15","budget":1250000,"budget_notes":"","update_owner":"נתנאל","major_issues":"הכנסת קבלן ליעד 2025.\nבירוקרטיה מוריה לח-ן סופי","followup_date":"2024-06-06","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":6}},{"project_id":"nave-7","condition":"לא סווג","updated_at":"2024-06-06","short_status":"ביצוע - ביצוע שוטף","manager_issue":"","detailed_status":"יעד מרץ 24:\nסה\"כ שצ\"פים בטיפול- 55\nהתקבלו אישורים נקיים- 32\nהתקבלו אישורים מוחרגים- 3\nהסתיים ביצוע בתהליך הוצאת אישור- 4\nבביצוע- 17\nיעד מרץ 25:\nאין עדיין גנים בביצוע, 11 גנים בהקמת חוזה.","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"עמית","major_issues":"\nבעיה : בזמן קבלת אישורים ראשונים לגנים נראה שיש עיכוב מצד יועץ הנגישות בפרויקט בזמני הנפקת אישורי נגישות.\nפתרון : נשלח מייל בתפוצה כללית ליועץ על מנת לרתום אותו לסייע בזמנים קצרים יותר לקבלת אישורי נגישות לגנים בפרויקט . \n\nבעיה: קבלן מנה ד''2 לא מצליח להיכנס לביצוע למעט גן אחד מתוך 3 גם שם מתקשה לאשר יציקה.\nפתרון: מעקב השלמת היערות קונס'' ליציקה והעברת 2 גנים נוספים לקבלן אחר.","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":7}},{"project_id":"nave-8","condition":"לא סווג","updated_at":"2024-04-25","short_status":"תכנון - תכנון מפורט","manager_issue":"","detailed_status":"עובדים על תיקוף סקרים וקידום תכנון יעד מרץ 25 ומרץ 26\n\nסה\"כ 61 מבנים\n38 בהליכי תכנון\nמתוכם : 9 בתהליך הוצאת היתר\n2 בבדיקת סטטוס מבנה והאם נדרש לבצע הנגשה או שהמבנה מתפנה\nמבנה 1 ממתין לתקצוב ביצוע שיפוץ כולל (מתחם שירותים ציבוריים)\n19 בהליכי תיקוף סקר\nמבנה 1 בבדיקה משפטית עקב סכסוך שכנים, וצורך באישור שכנים לביצוע","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"דוד","major_issues":"","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":8}},{"project_id":"nave-9","condition":"לא סווג","updated_at":"2024-04-25","short_status":"תכנון - תכנון מפורט","manager_issue":"","detailed_status":"אושרה רשימה ותוכנית עבודה מרץ 25.\nהושלמו סיורים עם אדריכלית, התחלנו לאשר תכניות מול יועצים וגורמי עירייה.\nעובדים על כתבי כמויות לשצפי\"ם בהם לא נדרש תכנון\n\nסה\"כ 54 שצפי\"ם\nמתוכם 10 בתכנון\n1 התקבל אישור נגישות","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"דוד","major_issues":"","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":9}},{"project_id":"nave-10","condition":"לא סווג","updated_at":"2024-04-25","short_status":"אחר - פירוט ב\"סטטוס מפורט\"","manager_issue":"","detailed_status":"קיימת רשימת מגרשים ליעד מרץ 25, כולל אומדן ראשוני.\nעובדים על בניית רשימת יועצים, נבחרו יועצים , בשלב אישור יועצים מול מוריה.\nכרגע מוקפא מטעמי חוסר תקציב עד קבלת השלמה.","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"דוד","major_issues":"","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":10}},{"project_id":"nave-11","condition":"לא סווג","updated_at":"2024-05-30","short_status":"אחר - פירוט ב\"סטטוס מפורט\"","manager_issue":"","detailed_status":"מרץ 2025:\nהתקבלו אישורים- 2\nהושלמו ממתינים לאישור- 1\n14 מבנים בביצוע.\n19 מבנים מוכנים, חוזים יוקמו בקרוב בהתאם לקבלת תקציב.\n59 מבנים בתכנון, מתוכם 14 בהליך היתר בניה.\nחלקם בתהליך תיקוף סקר.\n* דרישת הזמנת עבודה לשנת יעד 2025 יצאה אל רות חטאבי בנובמבר 23, התקבלה הזמנה חלקית על סך 2 מש\"ח בתאריך 02.05.24, הזמנה על סך 6 מש\"ח בהכנה.","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"נווה","major_issues":"בעיה: מצוקת כח עבודה.\nפתרון: עידוד קבלנים ע\"י תמריצים בצורת ריג''י.","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":11}},{"project_id":"nave-12","condition":"לא סווג","updated_at":"2024-05-30","short_status":"אחר - פירוט ב\"סטטוס מפורט\"","manager_issue":"","detailed_status":"1. חבילה ב'' 27 גנים- בביצוע, קבלן דודו חי- התקבלו 25 אישורים, מתוכם 2 מוחרגים, יש להשלים טיפול.\n2. חבילה ג'' 10 גנים- הסתיימו עבודות, התקבלו 9 אישורים, 1 בהמתנה.\n3. חבילה ד1 5 גנים- בביצוע עלמי נאטור.- התקבלו 1 אישורים.\n4. חבילה ד2 3 גנים - בביצוע קבלן אחזקת שבר.- התקבלו 0 אישורים.\n5. חבילה ה'' בת 8 שצ\"פים- עבר לקבלן שי חנופה תחת דודו חי, החל עבודות.\n* דרישת הזמנת עבודה לשנת יעד 2025 יצאה אל רות חטאבי, התקבלה הזמנה חלקית כ 0.9 מש\"ח, מכינים הזמנה לעוד 2 מש\"ח.\n* תוכנית עבודה מרץ 25 אושרה, התקבלו 2 אישורים, תכנון מתקדם ל 10 גנים , עוד 42 גנים מוכנים, יש תקציב רק ל 11 מתוכם, כתב כמויות נשלח לשפ\"ע לאישור לפני הקמת חוזה.","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"נווה","major_issues":"בעיה: קבלני אחזקה לא עובדים בקצב הנדרש ולא מגיעים לאישורים, כמו כן קבלן אחזקה תאופיק לא מצליח לגייס עובדים לפתיחת עבודות במנה ד2.\nפתרון: שיחות ולחצים על הקבלן, עירוב אגף שפ\"ע ומוריה לסיוע בהפעלת לחץ ומציאת פתרונות, ניסיון להעברת גנים ממנה ד2 לקבלן אחר.","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":12}},{"project_id":"nave-13","condition":"לא סווג","updated_at":"2024-05-30","short_status":"אחר - פירוט ב\"סטטוס מפורט\"","manager_issue":"","detailed_status":"חוזה קבלן גריפון לביצוע מנה בת 29 מתקנים- התקבלו 28 אישורי נגישות, אחרון בהמתנה.\nחוזי יועצים עלו למניפה בתאריך 03.12.23, אך הוקפאו מפאת חוסר תקציב, חודשו בתאריך 06.05.24 , מתואמת פגישת התנעת תכנון.\n*  הוקם חוזה ביצוע עבור 7 מגרשים פשוטים מתוכנית מרץ 25  לקבלן גריפון\n* הזמנת עבודה- התקבלה חלקית, נדרשת השלמה.","stage_due_date":"","budget":null,"budget_notes":"","update_owner":"נווה","major_issues":"בעיה: תקציבים, התקבלה הזמנה חלקית.\nפתרון: לקדם השלמת הזמנה מול רות חטאבי.","followup_date":"","manager_notes":"","source":{"workbook":"‏‏‏‏נווה - נגישות - טבלת סטטוס פרויקטים משרדית.xlsx","sheet":"נווה - נגישות","row":13}}],"project_status_updates":[],"requirements_tasks":[],"protocols":[],"vehicles":[],"mileage_entries":[],"leave_requests":[],"project_costs":[{"id":"nave-5-cost-0","project_id":"nave-5","chapter":"בינוי","contractual":0,"approved":0,"actual":0,"exceptions":0,"note":"טרם הוזנו עלויות","data_source":"manual"},{"id":"nave-5-cost-1","project_id":"nave-5","chapter":"חשמל","contractual":0,"approved":0,"actual":0,"exceptions":0,"note":"טרם הוזנו עלויות","data_source":"manual"},{"id":"nave-5-cost-2","project_id":"nave-5","chapter":"מיזוג אוויר","contractual":0,"approved":0,"actual":0,"exceptions":0,"note":"טרם הוזנו עלויות","data_source":"manual"},{"id":"nave-5-cost-3","project_id":"nave-5","chapter":"אינסטלציה","contractual":0,"approved":0,"actual":0,"exceptions":0,"note":"טרם הוזנו עלויות","data_source":"manual"},{"id":"nave-5-cost-4","project_id":"nave-5","chapter":"תקשורת","contractual":0,"approved":0,"ac